(function(){
if(window.__QMES_RECIPE_CHEM_MASTER_V5__)return;window.__QMES_RECIPE_CHEM_MASTER_V5__=true;
const KEY='qmes-bom-local-v1';let host=null,nativeHost=null,selectedId=null,lastSig='';
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const load=()=>{try{const a=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(a)?a:[]}catch(e){return[]}};
const store=a=>localStorage.setItem(KEY,JSON.stringify(a));
function user(){const u=window.__QMES_USER__||window.__QMES_CURRENT_USER__||{};return typeof u==='object'?(u.name||u.displayName||u.email||'로그인 사용자'):String(u||'로그인 사용자')}
function workOrders(){try{if(typeof DB==='undefined')return[];const docs=DB.woDocs||{};return Object.keys(docs).map(lot=>{const w=docs[lot]||{},b=(DB.batches||[]).find(x=>String(x.no||'')===String(lot))||{};return{lot,item:String(w.item||b.item||DB.lots?.[lot]?.itemName||''),plan:Number(w.plan||b.plan||0),unit:w.unit||b.unit||'kg',date:String(w.date||b.due||'').slice(0,10),tank:w.tank||b.tank||'',inputs:Array.isArray(w.inputs)?w.inputs:[],conds:Array.isArray(w.conds)?w.conds:[]}}).filter(x=>x.item)}catch(e){return[]}}
function nextRecipe(){return'RCP-'+String(load().length+1).padStart(3,'0')}
function statusBadge(s){const c=s==='사용중'?'#16a34a':s==='승인'?'#2563eb':s==='검토중'?'#f59e0b':s==='폐기'?'#64748b':'#475569';return `<span style="display:inline-block;padding:3px 8px;border-radius:999px;background:${c};color:#fff;font-size:11px;font-weight:800">${esc(s||'작성중')}</span>`}
function formulaRows(r){const a=r?.formula||[];if(!a.length)return'<tr><td colspan="12" style="text-align:center;color:#94a3b8;padding:22px">작업지시서를 선택하면 투입원료가 자동 작성됩니다.</td></tr>';return a.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.code||'')}</td><td>${esc(x.name)}</td><td>${esc(x.type||'원료')}</td><td>${esc(x.grade||'')}</td><td>${esc(x.ratio)}</td><td>${esc(x.std)}</td><td>${esc(x.tolerance||'±1%')}</td><td>${i+1}</td><td>${esc(x.process||'')}</td><td>${esc(x.ctq||'-')}</td><td>${esc(x.alt||'-')}</td></tr>`).join('')}
function html(){return `<div class="qmes-business-extension"><div class="qbe-title-row"><div><h1 class="qbe-title">Recipe / BOM Master</h1><div class="qbe-subtitle">작업지시서에서 BOM 초안 생성 → 저장 → 검토 → 승인 → 사용중 확정 순서로 관리합니다.</div></div></div>
<div class="qbe-card" style="padding:10px 12px"><div style="display:flex;gap:7px;align-items:center;flex-wrap:wrap"><button class="qbe-primary" data-a="import">작업지시서에서 BOM 생성</button><select id="qbm-wo" style="min-width:330px;padding:9px;border:1px solid #cbd5e1;border-radius:7px"><option value="">작업지시서 선택</option></select><button class="qbe-primary" data-a="save">저장</button><button class="qbe-primary" data-a="review" style="background:#f59e0b">검토요청</button><button class="qbe-primary" data-a="approve" style="background:#2563eb">승인</button><button class="qbe-primary" data-a="activate" style="background:#16a34a">사용중 확정</button><button class="qbe-primary" data-a="revision" style="background:#7c3aed">BOM 개정</button><button class="qbe-primary" data-a="print" style="background:#475569">인쇄</button><span id="qbm-msg" style="font-size:12px;font-weight:800;color:#2563eb"></span></div></div>
<div style="display:grid;grid-template-columns:.6fr 1.4fr;gap:12px"><div class="qbe-card"><div class="qbe-card-head"><h2>제품 목록</h2></div><div class="qbe-table-wrap"><table><thead><tr><th>제품코드/품목</th><th>Recipe</th><th>현재상태</th></tr></thead><tbody id="qbm-products"></tbody></table></div></div><div class="qbe-card"><div class="qbe-card-head"><h2>BOM / Revision 목록</h2><span class="qbe-hint">승인된 Revision 이력 보존</span></div><div class="qbe-table-wrap"><table><thead><tr><th>Revision</th><th>생성기준 LOT</th><th>기준 Batch</th><th>적용일</th><th>상태</th><th>승인자</th></tr></thead><tbody id="qbm-revs"></tbody></table></div></div></div>
<div class="qbe-card"><div class="qbe-card-head"><h2>선택 BOM 기본정보</h2><span class="qbe-hint" id="qbm-state">Master Data</span></div><div class="qbe-form-grid"><div class="qbe-field"><label>제품코드 / 품목</label><input data-f="productCode"></div><div class="qbe-field"><label>제품명</label><input data-f="productName"></div><div class="qbe-field"><label>생성기준 작업지시 LOT</label><input data-f="sourceLot" readonly></div><div class="qbe-field"><label>설비</label><input data-f="tank"></div><div class="qbe-field"><label>Recipe No.</label><input data-f="recipeNo"></div><div class="qbe-field"><label>Revision</label><input data-f="revision"></div><div class="qbe-field"><label>기준 Batch Size (kg)</label><input data-f="batchSize" type="number"></div><div class="qbe-field"><label>예상 수율 (%)</label><input data-f="yield" type="number"></div><div class="qbe-field"><label>적용일</label><input data-f="effectiveDate" type="date"></div><div class="qbe-field"><label>상태</label><select data-f="status" disabled><option>작성중</option><option>검토중</option><option>승인</option><option>사용중</option><option>폐기</option></select></div><div class="qbe-field"><label>변경내용</label><input data-f="changeNote"></div><div class="qbe-field"><label>작성 / 검토 / 승인</label><input data-f="approvalText" readonly placeholder="승인 이력 자동 기록"></div></div></div>
<div class="qbe-card"><div class="qbe-card-head"><h2>표준 배합표 (Formula)</h2><span class="qbe-hint">승인 후 Master BOM으로 사용</span></div><div class="qbe-table-wrap"><table><thead><tr><th>순번</th><th>원료코드</th><th>원료명</th><th>구분</th><th>Grade</th><th>배합비 %</th><th>기준량 kg</th><th>허용오차</th><th>투입순서</th><th>투입공정</th><th>CTQ</th><th>대체원료</th></tr></thead><tbody id="qbm-formula"></tbody></table></div></div>
<div class="qbe-card"><div class="qbe-card-head"><h2>공정조건</h2><span class="qbe-hint">작업지시 조건 자동 연동</span></div><div class="qbe-table-wrap"><table><thead><tr><th>순서</th><th>관리항목</th><th>기준값</th><th>실적값</th></tr></thead><tbody id="qbm-conds"></tbody></table></div></div></div>`}
function msg(t,c='#2563eb'){const e=host?.querySelector('#qbm-msg');if(e){e.textContent=t;e.style.color=c}}
function fields(){const o={};host.querySelectorAll('[data-f]').forEach(e=>o[e.dataset.f]=e.value.trim());return o}
function setFields(r={}){host.querySelectorAll('[data-f]').forEach(e=>e.value=r[e.dataset.f]||'');const st=host.querySelector('#qbm-state');if(st)st.innerHTML=`${statusBadge(r.status||'작성중')} ${r.approvedAt?`<span style="margin-left:6px">승인 ${esc(r.approvedAt)}</span>`:''}`}
function populateWO(force=false){if(!host)return;const s=host.querySelector('#qbm-wo'),orders=workOrders(),sig=orders.map(w=>`${w.lot}|${w.item}|${w.plan}|${w.unit}`).join('||');if(!force&&sig===lastSig)return;const cur=s.value;s.innerHTML='<option value="">작업지시서 선택</option>'+orders.map(w=>`<option value="${esc(w.lot)}">${esc(w.lot)} · ${esc(w.item)} · ${w.plan.toLocaleString()} ${esc(w.unit)}</option>`).join('');if(cur&&orders.some(w=>w.lot===cur))s.value=cur;lastSig=sig}
function renderConds(r){const b=host.querySelector('#qbm-conds'),a=r?.conds||[];b.innerHTML=a.length?a.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.name||x.label||'')}</td><td>${esc(x.std||x.target||x.spec||'')}</td><td>${esc(x.act||'-')}</td></tr>`).join(''):'<tr><td colspan="4" style="text-align:center;color:#94a3b8;padding:20px">등록된 공정조건이 없습니다.</td></tr>'}
function draftFromWO(lot){const w=workOrders().find(x=>x.lot===lot);if(!w){msg('작업지시서를 선택하세요.','#dc2626');return}const total=w.inputs.reduce((a,x)=>a+(Number(x.std)||0),0)||w.plan||0,old=load().find(x=>x.productCode===w.item&&x.status==='사용중');const formula=w.inputs.map((x,i)=>{const std=Number(x.std)||0;return{name:x.name||x.material||'',code:x.code||x.materialCode||'',type:typeof qmesMaterialType==='function'?qmesMaterialType(x.name):'원료',std,ratio:total?Number((std/total*100).toFixed(4)):0,tolerance:'±1%',process:x.process||'',ctq:x.ctq||'-',alt:'-'}});const r={id:'BOM-'+Date.now(),productCode:w.item,productName:w.item,sourceLot:w.lot,tank:w.tank,recipeNo:old?.recipeNo||nextRecipe(),revision:old?'Rev.'+String((parseInt(String(old.revision).replace(/\D/g,''),10)||0)+1).padStart(2,'0'):'Rev.01',batchSize:String(total||w.plan||''),yield:'100',effectiveDate:w.date||new Date().toISOString().slice(0,10),status:'작성중',changeNote:old?'기존 Master BOM 기준 신규 초안':'작업지시서 기준 최초 BOM 생성',approvalText:'작성: '+user(),createdBy:user(),createdAt:new Date().toISOString(),formula,conds:w.conds||[]};selectedId=r.id;host.__draft=r;setFields(r);host.querySelector('#qbm-formula').innerHTML=formulaRows(r);renderConds(r);msg(`${w.lot} 작업지시서에서 BOM 초안을 자동 작성했습니다.`,'#15803d')}
function render(){const a=load(),p=host.querySelector('#qbm-products'),r=host.querySelector('#qbm-revs');const products=[];a.forEach(x=>{if(!products.some(y=>y.productCode===x.productCode))products.push(x)});p.innerHTML=products.length?products.map(x=>`<tr data-id="${esc(x.id)}" style="cursor:pointer"><td>${esc(x.productCode)}</td><td>${esc(x.recipeNo)}</td><td>${statusBadge(x.status)}</td></tr>`).join(''):'<tr><td colspan="3" style="text-align:center;color:#94a3b8;padding:20px">저장된 BOM이 없습니다.</td></tr>';r.innerHTML=a.length?a.map(x=>`<tr data-id="${esc(x.id)}" style="cursor:pointer"><td>${esc(x.revision)}</td><td>${esc(x.sourceLot||'-')}</td><td>${esc(x.batchSize)}</td><td>${esc(x.effectiveDate)}</td><td>${statusBadge(x.status)}</td><td>${esc(x.approvedBy||'-')}</td></tr>`).join(''):'<tr><td colspan="6" style="text-align:center;color:#94a3b8;padding:20px">저장된 Revision이 없습니다.</td></tr>'}
function select(id){const x=load().find(v=>v.id===id);if(!x)return;selectedId=id;host.__draft=x;setFields(x);host.querySelector('#qbm-formula').innerHTML=formulaRows(x);renderConds(x);msg('저장된 BOM을 불러왔습니다.')}
function persist(d,text){let a=load(),i=a.findIndex(x=>x.id===d.id);if(i>=0)a[i]=d;else a.unshift(d);store(a);selectedId=d.id;host.__draft=d;setFields(d);render();msg(text,'#15803d')}
function saveDraft(){const f=fields(),base=host.__draft||{};if(!f.productCode||!f.recipeNo){msg('먼저 작업지시서에서 BOM을 생성하세요.','#dc2626');return}if(['승인','사용중','폐기'].includes(base.status)){msg('승인/사용중 BOM은 직접 수정할 수 없습니다. BOM 개정을 사용하세요.','#dc2626');return}persist({...base,...f,status:base.status||'작성중',id:selectedId||base.id||'BOM-'+Date.now()},'BOM을 저장했습니다.')}
function changeStatus(next){const d=host.__draft;if(!d){msg('먼저 BOM을 저장하거나 선택하세요.','#dc2626');return}if(next==='검토중'&&d.status!=='작성중'){msg('작성중 BOM만 검토 요청할 수 있습니다.','#dc2626');return}if(next==='승인'&&d.status!=='검토중'){msg('검토중 BOM만 승인할 수 있습니다.','#dc2626');return}if(next==='사용중'&&d.status!=='승인'){msg('승인된 BOM만 사용중으로 확정할 수 있습니다.','#dc2626');return}const now=new Date().toISOString().slice(0,16).replace('T',' '),u=user(),x={...d,...fields(),status:next};if(next==='검토중'){x.reviewedBy=u;x.reviewedAt=now;x.approvalText=`작성: ${x.createdBy||u} / 검토요청: ${u}`}if(next==='승인'){x.approvedBy=u;x.approvedAt=now;x.approvalText=`작성: ${x.createdBy||u} / 검토: ${x.reviewedBy||'-'} / 승인: ${u}`}if(next==='사용중'){let a=load().map(v=>v.productCode===x.productCode&&v.id!==x.id&&v.status==='사용중'?{...v,status:'폐기'}:v);store(a);x.activatedBy=u;x.activatedAt=now;x.approvalText=`작성: ${x.createdBy||u} / 검토: ${x.reviewedBy||'-'} / 승인: ${x.approvedBy||'-'} / 사용중 확정: ${u}`}persist(x,next==='사용중'?'Master BOM으로 사용중 확정했습니다. 이후 작업지시는 이 Revision을 참조합니다.':`${next} 상태로 변경했습니다.`)}
function revision(){const s=host.__draft;if(!s){msg('개정할 BOM을 선택하세요.','#dc2626');return}if(!['승인','사용중'].includes(s.status)){msg('승인 또는 사용중 BOM에서 개정본을 생성하세요.','#dc2626');return}const n=(parseInt(String(s.revision).replace(/\D/g,''),10)||0)+1,d={...s,id:'BOM-'+Date.now(),revision:'Rev.'+String(n).padStart(2,'0'),status:'작성중',changeNote:'BOM 개정',effectiveDate:new Date().toISOString().slice(0,10),sourceRevision:s.revision,createdBy:user(),createdAt:new Date().toISOString(),reviewedBy:'',reviewedAt:'',approvedBy:'',approvedAt:'',activatedBy:'',activatedAt:'',approvalText:'작성: '+user()};selectedId=d.id;host.__draft=d;setFields(d);host.querySelector('#qbm-formula').innerHTML=formulaRows(d);renderConds(d);msg(`${d.revision} 개정 초안을 생성했습니다. 기존 ${s.revision}은 보존됩니다.`,'#15803d')}
function wire(){host.addEventListener('click',e=>{const tr=e.target.closest('[data-id]');if(tr){select(tr.dataset.id);return}const b=e.target.closest('[data-a]');if(!b)return;const a=b.dataset.a;if(a==='import')draftFromWO(host.querySelector('#qbm-wo').value);else if(a==='save')saveDraft();else if(a==='review')changeStatus('검토중');else if(a==='approve')changeStatus('승인');else if(a==='activate')changeStatus('사용중');else if(a==='revision')revision();else if(a==='print')window.print()})}
function mount(){const h=document.getElementById('qmes-business-extension-host');if(!h||!h.querySelector('.qbe-title,h1')?.textContent.includes('Recipe / BOM Master'))return;if(host&&document.body.contains(host))return;nativeHost=h;host=document.createElement('div');host.id='qmes-chemical-bom-v5-host';host.innerHTML=html();h.parentNode.insertBefore(host,h);h.style.display='none';wire();lastSig='';populateWO(true);render()}
function unmount(){if(!host)return;const active=document.querySelector('[data-qbe-menu="recipe"] .qmes-top-menu-button.is-active,[data-qbe-menu="recipe"] button.is-active');if(!active){host.remove();host=null;lastSig='';if(nativeHost&&document.body.contains(nativeHost))nativeHost.style.removeProperty('display');nativeHost=null}}
new MutationObserver(()=>{mount();unmount()}).observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});document.addEventListener('click',e=>{if(e.target.closest('[data-qbe-menu="recipe"]'))setTimeout(mount,100);else if(e.target.closest('.qmes-top-menu-button'))setTimeout(unmount,100)},true);setInterval(()=>{mount();if(host)populateWO(false)},2500);
})();